<template>
 <ThemePage><view class="orders-page" data-promoter-orders>
  <view class="search-header"><view class="search-pill"><text class="search-icon">⌕</text><input v-model="state.keyword" confirm-type="search" maxlength="128" placeholder="搜索商品名称" aria-label="搜索商品名称" @confirm="state.search"/><button class="search-button" @tap="state.search">搜索</button></view></view>
  <view class="time-slot"><view class="time-presets"><button v-for="item in periods" :key="item.value" :class="{selected:state.period===item.value}" @tap="state.choosePeriod(item.value)">{{ item.label }}</button></view><button class="custom-toggle" :class="{selected:state.period==='custom'}" @tap="state.customOpen=!state.customOpen">自定义时间⌄</button></view>
  <view v-if="state.customOpen" class="custom-range"><view class="date-pickers"><picker mode="date" :value="state.startDay" start="1970-01-02" end="2038-01-18" @change="changeStart"><view>开始日期 <text>{{ state.startDay }}</text></view></picker><picker mode="date" :value="state.stopDay" start="1970-01-02" end="2038-01-18" @change="changeStop"><view>结束日期 <text>{{ state.stopDay }}</text></view></picker></view><button class="apply-range" @tap="state.applyCustom">查询所选日期</button></view>
  <view v-if="state.period==='custom' && !state.customOpen" class="range-caption">{{ state.appliedDates.start }} 至 {{ state.appliedDates.stop }}（上海时间）</view>
  <view v-if="state.filterError" class="order-state order-error" role="alert">{{ state.filterError }}</view>
  <view v-if="!state.loggedIn" class="order-state"><view>登录后查看分销订单</view><button class="order-control" @tap="state.login">去登录</button></view>
  <template v-else>
   <view v-if="state.loaded" class="order-summary">共 <text>{{ state.count }}</text> 笔订单，获得佣金 ¥<text>{{ state.sum }}</text><view v-if="state.appliedKeyword" class="summary-note">订单按关键词筛选；佣金合计按所选时间统计</view></view>
   <view v-for="group in state.groups" :key="group.month" :data-order-month="group.month"><view v-for="row in group.rows" :key="row.id" class="order-card" :data-promoter-order-id="row.id">
    <view class="order-top"><view class="buyer"><view class="buyer-avatar"><image v-if="row.image.src" :key="row.image.key" :src="row.image.src" mode="aspectFill" @error="row.image.error"/><text v-else>{{ (row.nickname || '用户').slice(0,1) }}</text></view><text class="buyer-name">{{ row.nickname || '用户' }}</text></view><text v-if="row.is_frozen" class="frozen">冻结</text><view class="commission" :class="{pending:row.type==='number'}">{{ row.type==='brokerage'?'返佣：¥':'暂未返佣：￥' }}<text>{{ row.number }}</text></view></view>
    <view class="order-bottom"><view class="product-line"><text class="field-label">宝贝名称：</text><text class="product-title">{{ row.store_name }}</text></view><view><text class="field-label">{{ row.type==='brokerage'?'返佣时间：':'下单时间：' }}</text>{{ row.time }}</view></view>
   </view></view>
   <view v-if="state.loading" class="order-state" role="status">分销订单读取中…</view>
   <view v-if="state.error" class="order-state order-error" role="alert">{{ state.error }}</view>
   <view v-if="state.loaded && !state.loading && !state.error && !state.items.length" class="order-empty"><image src="/static/php-points/noOrder.gif" mode="aspectFit"/><view>暂无推广订单～</view></view>
   <button v-if="state.error" class="order-control" :disabled="state.loading" @tap="state.retry">重试当前页</button>
   <button v-if="state.hasMore && !state.error" class="order-control" :disabled="state.loading" @tap="state.load(true)">{{ state.loading?'读取中…':'加载更多' }}</button>
   <view v-if="state.loaded && state.items.length && !state.hasMore && !state.loading && !state.error" class="order-state">{{ state.page===1000?'已显示前10000笔订单':'没有更多了～' }}</view>
   <view v-if="state.mediaExpired" class="order-state">头像已过期，请刷新订单</view><button class="order-control" :disabled="state.loading" @tap="state.refresh">刷新订单</button>
  </template>
 </view></ThemePage>
</template>
<script setup lang="ts">
import {reactive} from 'vue';
import ThemePage from '@/components/ThemePage.vue';
import {usePromoterOrders} from '@/composables/usePromoterOrders';
import type {OrderPeriod} from '@/api/promoterOrders';
const state=reactive(usePromoterOrders());
const periods:{value:Exclude<OrderPeriod,'custom'>;label:string}[]=[{value:'all',label:'全部'},{value:'today',label:'今日'},{value:'yesterday',label:'昨日'},{value:'seven',label:'近7日'}];
function changeStart(event:{detail:{value:string}}){state.startDay=event.detail.value;}
function changeStop(event:{detail:{value:string}}){state.stopDay=event.detail.value;}
</script>
